import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { User, LoginRequest, RegisterRequest } from '../models/user';
import { environment } from '../../../environments/environment';
import { jwtDecode } from 'jwt-decode';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private apiUrl = `${environment.apiUrl}/auth`;
  private currentUserSubject = new BehaviorSubject<User | null>(this.getStoredUser());
  currentUser$ = this.currentUserSubject.asObservable();

  constructor(private http: HttpClient) {}

  private getStoredUser(): User | null {
    const stored = localStorage.getItem('shopez_user');
    return stored ? JSON.parse(stored) : null;
  }

  get currentUser(): User | null { return this.currentUserSubject.value; }
  get isLoggedIn(): boolean { return !!this.currentUserSubject.value; }
  get isAdmin(): boolean { return this.currentUserSubject.value?.role === 'admin'; }

  // POST /api/auth/register
  register(data: RegisterRequest): Observable<User> {
    return this.http.post<User>(`${this.apiUrl}/register`, data).pipe(
      tap(user => {
        localStorage.setItem('shopez_user', JSON.stringify(user));
        this.currentUserSubject.next(user);
      })
    );
  }

  // POST /api/auth/login → { token }
  login(credentials: LoginRequest): Observable<{ token: string }> {
    return this.http.post<{ token: string }>(`${this.apiUrl}/login`, credentials).pipe(
      tap(response => {
        const token = response.token;
        const decoded: any = jwtDecode(token);
        const user: User = {
          id: decoded.nameid || decoded.sub || decoded.userId,
          name: decoded.unique_name || decoded.name || decoded.email,
          email: decoded.email || credentials.email,
          role: (decoded.role || decoded.Role || 'customer').toLowerCase(),
          token: token
        };
        localStorage.setItem('shopez_user', JSON.stringify(user));
        this.currentUserSubject.next(user);
      })
    );
  }

  logout(): void {
    localStorage.removeItem('shopez_user');
    this.currentUserSubject.next(null);
  }
}
